export function createPuzzle(id){if(!Number.isInteger(id)||!puzzles[id])throw new Error('Unknown encounter.');return {id,time:puzzles[id].stage===0?100:0,paused:false,rewound:false,seenFuture:false,returned:false,flags:[],solved:false,message:puzzles[id].before,history:[]};}
export function reducePuzzle(state,event){
 if(!event||typeof event.type!=='string')throw new Error('Choose a valid action.');
 const q=puzzles[state.id],s={...state,flags:[...state.flags],history:[...state.history,event]};
 if(s.history.length>120)throw new Error('Reset this attempt to keep the timeline light.');
 if(s.solved){s.message='This little moment is already restored.';return s;}
 const type=event.type;
 if(type==='rewind'){if(q.stage!==0)throw new Error('This spirit has a different gift.');s.time=0;s.paused=true;s.rewound=true;s.message='The memory is back at its beginning. Change what happens next.';}
 else if(type==='pause'){if(q.stage!==1)throw new Error('Use this chapter’s time controls.');s.time=45;s.paused=true;s.message='The market is still. Look at the scene and offer a helping hand.';}
 else if(type==='preview'){if(q.stage!==2)throw new Error('Only the future spirit can look ahead.');s.time=100;s.paused=false;s.seenFuture=true;s.message=q.before;}
 else if(type==='return'){if(q.stage!==2||!s.seenFuture)throw new Error('Look ahead once before returning to the choice.');s.time=0;s.paused=true;s.returned=true;s.message='A future seen is not a future fixed. Change this moment.';}
 else if(type==='resume'){if(q.stage===2)throw new Error('Preview tomorrow to see the consequence.');s.time=100;s.paused=false;s.message=q.before;}
 else {
 const a=q.actions.find(a=>a.id===type);if(!a)throw new Error('That object cannot change this scene.');
 if(q.stage===0&&(!s.rewound||s.time!==0))throw new Error('Rewind to before the missed moment first.');
 if(q.stage===1&&!s.paused)throw new Error('Pause the market before helping. There is no hurry.');
 if(q.stage===2&&(!s.seenFuture||!s.returned||s.time!==0))throw new Error('Preview tomorrow, then return to the choice before changing it.');
 if(a.requires.some(f=>!s.flags.includes(f)))throw new Error('One small step comes first. Look for what this action needs.');
 if(!s.flags.includes(type))s.flags.push(type);
 s.message=a.label+' — a little kindness is taking shape.';
 }
 if(s.time===100&&q.actions.every(a=>s.flags.includes(a.id))&&(q.stage!==2||s.returned)){s.solved=true;s.message=q.after;}
 return s;
}
export function validateCompletion(id,events){if(!Array.isArray(events)||events.length>120)throw new Error('Invalid puzzle history.');let state=createPuzzle(id);for(const e of events)state=reducePuzzle(state,e);if(!state.solved)throw new Error('Change the scene and watch the outcome before collecting kindness.');return state;}
